  const hint={'mountain-connect':'見晴らし台からは先へ進めません。尾根か森の道から試してみましょう。','mountain-hops':'尾根を通る道と森の道を通る道で、矢印の数を比べてみましょう。','mountain-time':'尾根を通ると5分と5分、森の道を通ると2分ずつ3回です。'}[id];
  app.innerHTML=`<h1>${quest.title}</h1>${dialogue('sora',intro)}<section class="panel"><h2>目標：${quest.goal}</h2><p>地図の行きたい場所を選びましょう。今いる場所から進めない場所は選べません。矢印は進める向きを表し、場所をつなぐ矢印が一つの道です。道のそばに書かれた数字は所要時間です。</p><div class="mountain-map interactive-map route-map" role="group" aria-label="山道の地図。中継所から尾根、森の道、見晴らし台へ進めます。尾根から集落へ、森の道から小川を通って集落へ進めます。見晴らし台から先へは進めません。"><div class="map-canvas"><svg viewBox="0 0 600 260" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#547a5e"/></marker></defs><g fill="none" stroke="#547a5e" stroke-width="3" marker-mid="url(#arrow)"><path d="M78 130 L168 87.5 L258 45 M78 130 L168 130 L258 130 M78 130 L168 172.5 L258 215 M258 130 L390 130 L522 130 M258 215 Q258 247 336 247 Q414 247 414 215 M414 215 L468 172.5 L522 130"/></g></svg><span class="map-time rt-1">1分</span><span class="map-time rt-2">5分</span><span class="map-time rt-3">2分</span><span class="map-time rt-4">5分</span><span class="map-time rt-5">2分</span><span class="map-time rt-6">2分</span>${mountainButtonOrder.map(node=>`<button class="map-place place-${node}" data-mountain-next="${node}" aria-label="${mountainNames[node]}へ進む" ${result.done||!result.next.includes(node)?'disabled':''}>${mountainNames[node]}</button>`).join('')}</div></div><ul class="map-description" aria-label="道と所要時間">${edges}</ul><p>今までの道：${path}</p><p>通った道：${result.hops}本、所要時間の合計：${result.time}分</p><p id="mountain-status" tabindex="-1" role="status">${message}</p><details><summary>手がかりを聞く</summary><p>${hint}</p></details>${warning()}<div class="actions"><button id="undo" ${route.length?'':'disabled'}>一つ前に戻る</button><button id="reset">この依頼を最初からやり直す</button><button id="back">中継所へ戻る</button></div></section>${result.done?`<section class="panel result"><h2>目標を達成しました！</h2><button id="open-result" class="primary">達成の場面を見る</button></section><dialog id="success-dialog" class="story-success" aria-labelledby="mountain-success"><h2 id="mountain-success">依頼達成<span class="success-detail">${quest.title}</span></h2>${dialogue('sora','知らせが届いたよ！ 一緒に道を考えてくれてありがとう。')}<div class="actions"><button id="finish" class="primary">結果を見届ける</button><button id="review">選んだ道を見る</button></div></dialog>`:''}`;
  app.querySelectorAll('[data-mountain-next]').forEach(b=>b.onclick=()=>{state.mountainRoutes[id]=[...route,b.dataset.mountainNext];persist();mountainQuest();const current=mountainReplay(id,state.mountainRoutes[id]);if(current.done)app.querySelector('#success-dialog').showModal();else {const status=app.querySelector('#mountain-status');status.tabIndex=-1;status.focus({preventScroll:true});}});
  app.querySelector('#undo').onclick=()=>{state.mountainRoutes[id]=route.slice(0,-1);persist();mountainQuest();app.querySelector('#mountain-status').focus({preventScroll:true});};
  app.querySelector('#reset').onclick=()=>{if(!window.confirm('この依頼の道を最初から選び直しますか？'))return;state.mountainRoutes[id]=[];persist();mountainQuest();app.querySelector('[data-mountain-next]:not(:disabled)')?.focus();};
  app.querySelector('#back').onclick=()=>show('mountain');
