  app.querySelector('#back').onclick=()=>show(q.region==='tower'?'sky':'mist');
  const dialog=app.querySelector('#success-dialog');if(dialog){let reviewing=false;app.querySelector('#open-result').onclick=()=>dialog.showModal();app.querySelector('#review').onclick=()=>{reviewing=true;dialog.close();};app.querySelector('#finish').onclick=()=>{dialog.close();state.completed=completeQuest(state.completed,id);show('tower-gate-result');};dialog.addEventListener('close',()=>{if(!app.contains(dialog))return;if(reviewing){reviewing=false;app.querySelector('#tg-status').focus({preventScroll:true});}else app.querySelector('#open-result')?.focus({preventScroll:true});});}
